const http = require("http");
const fs = require("fs");
const path = require("path");
const puppeteer = require("puppeteer-core");

const mime = {
  ".html": "text/html",
  ".js": "application/javascript",
  ".css": "text/css",
  ".jpg": "image/jpeg"
};

const server = http.createServer((req, res) => {
  let filePath = "." + (req.url === "/" ? "/index.html" : req.url.split("?")[0]);
  const ext = path.extname(filePath);
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("Not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime[ext] || "text/plain" });
    res.end(data);
  });
});

server.listen(0, async () => {
  const port = server.address().port;
  const browser = await puppeteer.launch({
    executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    headless: "new",
    args: ["--no-sandbox", "--disable-setuid-sandbox"]
  });
  const page = await browser.newPage();
  const errors = [];
  page.on("console", msg => {
    if (msg.type() === "error") errors.push("CONSOLE ERROR: " + msg.text());
  });
  page.on("pageerror", err => errors.push("PAGE ERROR: " + err.message));

  await page.setViewport({ width: 1400, height: 920, deviceScaleFactor: 1.5 });
  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle0" });
  await new Promise(r => setTimeout(r, 600));

  // Shot 1: Hero + Scale 1
  await page.screenshot({ path: "shot-1-hero-cpr.jpg", type: "jpeg", quality: 85 });

  // Scroll to Scale 2 & Scale 3
  await page.evaluate(() => document.getElementById("scale-2").scrollIntoView());
  await new Promise(r => setTimeout(r, 400));
  await page.screenshot({ path: "shot-2-breath.jpg", type: "jpeg", quality: 85 });

  await page.evaluate(() => document.getElementById("scale-3").scrollIntoView());
  await new Promise(r => setTimeout(r, 400));
  await page.screenshot({ path: "shot-3-conflict.jpg", type: "jpeg", quality: 85 });

  // Scroll to Scale 4 & Scale 5
  await page.evaluate(() => document.getElementById("scale-4").scrollIntoView());
  await new Promise(r => setTimeout(r, 400));
  await page.screenshot({ path: "shot-4-water.jpg", type: "jpeg", quality: 85 });

  await page.evaluate(() => document.getElementById("scale-5").scrollIntoView());
  await page.click("#cal-reveal-btn");
  await new Promise(r => setTimeout(r, 400));
  await page.screenshot({ path: "shot-5-leverage.jpg", type: "jpeg", quality: 85 });

  // Scroll to Scale 6 (Pocket Card)
  await page.evaluate(() => document.getElementById("scale-6").scrollIntoView());
  await new Promise(r => setTimeout(r, 400));
  await page.screenshot({ path: "shot-6-card.jpg", type: "jpeg", quality: 85 });

  console.log("Errors count:", errors.length);
  if (errors.length) console.error(errors.join("\n"));

  await browser.close();
  server.close();
});
'

